// Block (composition) — responsive filters with active tags and a clear action.
// Arranges only; composes Select/TagGroup/Button/Stack.
import type { Ref } from "react";
import { Select, SelectItem } from "../components/Select";
import { Tag, TagGroup } from "../components/TagGroup";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./FilterBar.css";

export interface FilterBarProps {
  filters: {
    name: string;
    label: string;
    options: { id: string; label: string }[];
  }[];
  /**
   * The selected option id per filter `name`, making that filter's Select controlled. Pass it with
   * `onChange` when the page resets filters itself (`onClear`): an uncontrolled Select keeps showing
   * the old choice after a reset, and re-picking that choice fires no change.
   */
  values?: Record<string, string>;
  onChange?: (name: string, value: string) => void;
  onClear?: () => void;
  activeTags?: { id: string; label: string }[];
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function FilterBar({
  filters,
  values,
  onChange,
  onClear,
  activeTags,
  className,
  ref,
}: FilterBarProps) {
  return (
    <Stack
      ref={ref}
      direction={{ small: "column", medium: "row" }}
      gap="medium"
      // End, not centre: a Select's box sits under its label, so centring put the Clear button
      // and the tags half a label higher than the field they act on.
      align={{ small: "stretch", medium: "end" }}
      className={className ? `sd-filterbar ${className}` : "sd-filterbar"}
    >
      {filters.map((filter) => (
        <Select
          key={filter.name}
          className="sd-filterbar__filter"
          label={filter.label}
          name={filter.name}
          // Once `values` is passed every Select stays controlled: a missing key clears it (null)
          // rather than handing back control (undefined) and keeping the old choice.
          selectedKey={values === undefined ? undefined : (values[filter.name] ?? null)}
          placeholder={`All ${filter.label.toLowerCase()}`}
          onSelectionChange={(value) => {
            if (value !== null) onChange?.(filter.name, String(value));
          }}
        >
          {filter.options.map((option) => (
            <SelectItem key={option.id} id={option.id}>
              {option.label}
            </SelectItem>
          ))}
        </Select>
      ))}
      {activeTags && activeTags.length > 0 && (
        <TagGroup aria-label="Active filters" className="sd-filterbar__tags">
          {activeTags.map((tag) => (
            <Tag key={tag.id} id={tag.id}>
              {tag.label}
            </Tag>
          ))}
        </TagGroup>
      )}
      <Button type="button" variant="secondary" onPress={onClear}>
        Clear
      </Button>
    </Stack>
  );
}

/* FilterBar.css — full-width responsive arrangement only. */
.sd-filterbar {
  width: 100%;
}

.sd-filterbar__filter {
  min-width: 10rem;
}

.sd-filterbar__tags {
  flex: 1;
}
